// Build Date Window — Run once for all items: AN
const items = $input.all(); // alle eingehenden Items

function toEutilsDate(d) {
  return String(d || '20251001').replaceAll('-', ''); // YYYYMMDD
}

const today = new Date();
const yyyy = today.getFullYear();
const mm = String(today.getMonth() + 1).padStart(2, '0');
const dd = String(today.getDate()).padStart(2, '0');

const maxdate = `${yyyy}${mm}${dd}`;
const today_sql = `${yyyy}-${mm}-${dd}`;

return items.map(({ json }) => {
  const { query_id, query, last_run } = json;
  return {
    json: {
      query_id,
      query,
      mindate: toEutilsDate(last_run),
      maxdate,
      datetype: 'edat',
      today_sql
    }
  };
});

// Robustes Parsen von EPO OPS "biblio" JSON (EP/WIPO=Arrays; US/DE/CN=Objekte)

const root = $input.first().json?.["ops:world-patent-data"]?.["exchange-documents"]?.["exchange-document"] ?? {};

//
// Hilfsfunktionen
//
const asArray = (v) => v == null ? [] : (Array.isArray(v) ? v : [v]);

// Holt entweder obj.$ oder den String selbst
const val = (v, fallback = "") => {
  if (v == null) return fallback;
  if (typeof v === "object" && "$" in v && typeof v.$ === "string") return v.$;
  if (typeof v === "string") return v;
  return fallback;
};

// Holt das erste Element, das predicate erfüllt – über Arrays/Objekte hinweg
const firstMatch = (arrOrObj, predicate) => {
  for (const x of asArray(arrOrObj)) {
    if (predicate(x)) return x;
  }
  return undefined;
};

// YYYYMMDD -> YYYY-MM-DD (nur wenn 8-stellig)
const normDate = (s) => {
  const d = (s || "").toString();
  if (/^\d{8}$/.test(d)) return `${d.slice(0,4)}-${d.slice(4,6)}-${d.slice(6,8)}`;
  return d || "";
};

//
// Pfadkürzel
//
const biblio = root?.["bibliographic-data"] ?? {};

// 1) Publikationsnummer (epodoc)
let epodoc = "";

// Manche Datensätze haben mehrere document-id; häufig ist [1] epodoc, aber nicht garantiert.
// Wir suchen gezielt nach @document-id-type === "epodoc", andernfalls nehmen wir die erste doc-number.
const pubRef = biblio?.["publication-reference"]?.["document-id"];
const docIds = asArray(pubRef);

const epodocDoc = firstMatch(docIds, d => d?.["@document-id-type"] === "epodoc") ?? docIds[0];
epodoc = val(epodocDoc?.["doc-number"]);

// 2) Priorität (YYYY-MM-DD aus YYYYMMDD), bevorzugt epodoc
let priority = "";

const prioClaims = biblio?.["priority-claims"]?.["priority-claim"];
const prioDocs = asArray(prioClaims).map(pc => pc?.["document-id"]).flatMap(asArray);

// zuerst epodoc, sonst erstes Datum
let prio = firstMatch(prioDocs, d => d?.["@document-id-type"] === "epodoc") ?? prioDocs[0];

if (prio) {
  const ds = val(prio?.date);
  priority = normDate(ds);
}

// 3) Anmelder (epodoc)
let applicant = "";
const applicants = biblio?.parties?.applicants?.applicant;
const applList = asArray(applicants).filter(a => a?.["@data-format"] === "epodoc" || !a?.["@data-format"]);

const applicantNames = applList
  .map(a => val(a?.["applicant-name"]?.name))
  .filter(Boolean);

if (applicantNames.length === 0) {
  // Fallback: nimm alles, was da ist
  const allApps = asArray(applicants).map(a => val(a?.["applicant-name"]?.name)).filter(Boolean);
  applicant = allApps.join("; ");
} else {
  applicant = applicantNames.join("; ");
}

// 4) Erfinder (epodoc, kommasepariert)
let inventors = "";
const inventorsRaw = biblio?.parties?.inventors?.inventor;
const invList = asArray(inventorsRaw).filter(i => i?.["@data-format"] === "epodoc" || !i?.["@data-format"]);

const inventorNames = invList
  .map(i => val(i?.["inventor-name"]?.name))
  .filter(Boolean);

if (inventorNames.length === 0) {
  const allInv = asArray(inventorsRaw).map(i => val(i?.["inventor-name"]?.name)).filter(Boolean);
  inventors = allInv.join(", ");
} else {
  inventors = inventorNames.join(", ");
}

// 5) Titel (bevorzugt EN, sonst erster)
let title = "";
const titles = asArray(biblio?.["invention-title"]);
const titleEn = firstMatch(titles, t => (t?.["@lang"] || t?.["@lang"] === "en" || t?.["@lang"]?.toLowerCase?.() === "en")) ?? titles[0];
title = val(titleEn);

// 6) Abstract (bevorzugt EN, sonst erster). Struktur: abstract[].p.$ oder abstract.p.$
let abstractText = "";
const abstracts = asArray(root?.abstract);
const absEn = firstMatch(abstracts, a => (a?.["@lang"] || a?.["@lang"] === "en" || a?.["@lang"]?.toLowerCase?.() === "en")) ?? abstracts[0];

if (absEn) {
  // p kann Array, Objekt oder String sein
  const p = absEn?.p;
  if (Array.isArray(p)) {
    abstractText = p.map(x => val(x)).filter(Boolean).join("\n");
  } else {
    abstractText = val(p) || val(absEn); // Fallback auf gesamten Knoten
  }
}

return {
  epodoc,
  priority,
  applicant,
  inventors,
  title,
  abstract: abstractText
};

function strip4Byte(s) {
  if (!s) return s;
  // 4-Byte entfernen (Emojis etc.)
  s = s.replace(/[\uD800-\uDBFF][\uDC00-\uDFFF]/g, '');
  // optional: Unicode-Normalisierung (NFC), falls Node-Version es kann
  if (typeof s.normalize === 'function') s = s.normalize('NFC');
  return s;
}

const json = $('Loop Over Items1').first().json;

const titel = strip4Byte(json.PatentResultTitel);
const erfinder = strip4Byte(json.PatentResultErfinder)
const jahr = (json.PatentResultPublishedDate).substring(0,4);
const anmelder = json.PatentResultAnmelder ? json.PatentResultAnmelder : '';
const journal = "Patent";
const patentnr = json.PatentResultPublicationNumber;
const inseriert = json.PatentResultInseriert;
const abstract = strip4Byte(json.PatentResultAbstract);
const keywords = strip4Byte(json.PatentResultKeywords);

return {
  titel: titel,
  erfinder: erfinder,
  jahr: jahr,
  anmelder: anmelder,
  journal: journal,
  patentnr: patentnr,
  inseriert: inseriert,
  abstract: abstract,
  keywords: keywords
};

